import test from 'node:test';import assert from 'node:assert/strict';const api=await import('../src/latest-render-queue.mjs').catch(()=>({}));
const defer=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};};
test('latest-only queue executes at most one job and one replacement, never publishes a stale result',async()=>{assert.equal(typeof api.LatestRenderQueue,'function');const gate=defer(),executed=[],published=[],pending=[];const q=new api.LatestRenderQueue(async x=>{executed.push(x.n);return x.n===1?gate.promise:x.n;},{onPending:id=>pending.push(id),onResult:(r,id)=>published.push([r,id])});const a=q.submit({n:1}),b=q.submit({n:2}),c=q.submit({n:3});assert.equal((await b).status,'superseded');gate.resolve(1);assert.equal((await a).status,'superseded');assert.equal((await c).status,'ready');assert.deepEqual(executed,[1,3]);assert.deepEqual(published,[[3,3]]);assert.deepEqual(pending,[1,2,3]);});
test('submitted observer/options are snapshotted before execution',async()=>{assert.equal(typeof api.LatestRenderQueue,'function');const gate=defer(),seen=[];const q=new api.LatestRenderQueue(async x=>{seen.push(x.observer.utcMs);return x.n===1?gate.promise:1;});const a=q.submit({n:1,observer:{utcMs:10}}),job={n:2,observer:{utcMs:20}},b=q.submit(job);job.observer.utcMs=99;gate.resolve(1);await a;await b;assert.deepEqual(seen,[10,20]);});
test('worker errors cannot hang queue; later valid submission recovers',async()=>{assert.equal(typeof api.LatestRenderQueue,'function');const errors=[];const q=new api.LatestRenderQueue(async x=>{if(x.bad)throw Error('failed worker');return 4;},{onError:e=>errors.push(e.message)});assert.equal((await q.submit({bad:true})).status,'error');assert.equal((await q.submit({bad:false})).status,'ready');assert.deepEqual(errors,['failed worker']);});
test('disposal cancels pending and suppresses all late publishing',async()=>{assert.equal(typeof api.LatestRenderQueue,'function');const gate=defer(),published=[];const q=new api.LatestRenderQueue(()=>gate.promise,{onResult:r=>published.push(r)});const a=q.submit({n:1}),b=q.submit({n:2});q.dispose();assert.equal((await b).status,'disposed');gate.resolve(1);assert.equal((await a).status,'disposed');assert.equal((await q.submit({n:3})).status,'disposed');assert.deepEqual(published,[]);});
test('uncloneable newest input immediately supersedes an already pending job rather than spending CPU on it',async()=>{
 const gate=defer(),executed=[],q=new api.LatestRenderQueue(async j=>{executed.push(j.n);return gate.promise;});const a=q.submit({n:1});let pendingStatus=null;const b=q.submit({n:2}).then(x=>{pendingStatus=x.status;return x;});const invalid=await q.submit({callback:()=>{}});assert.equal(invalid.status,'error');await Promise.resolve();assert.equal(pendingStatus,'superseded');gate.resolve(1);await a;await b;assert.deepEqual(executed,[1]);
});
